import React, { useEffect, useState, useCallback } from 'react';
import { useSearchParams } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { healthService, animalService } from '../services/api';
import toast from 'react-hot-toast';
import { Plus, Trash2, Filter, X, Bell } from 'lucide-react';

const RECORD_TYPES = {
  vaccination: { label: 'Aşı', color: 'bg-blue-100 text-blue-700' },
  medication: { label: 'İlaç', color: 'bg-green-100 text-green-700' },
  examination: { label: 'Muayene', color: 'bg-purple-100 text-purple-700' },
  disease: { label: 'Hastalık', color: 'bg-red-100 text-red-700' },
  surgery: { label: 'Cerrahi', color: 'bg-orange-100 text-orange-700' },
  other: { label: 'Diğer', color: 'bg-gray-100 text-gray-700' }
};

const formatDate = (dateStr) => {
  if (!dateStr) return '—';
  try {
    const d = new Date(dateStr);
    if (isNaN(d.getTime())) return String(dateStr).slice(0, 10);
    return d.toLocaleDateString('tr-TR', { year: 'numeric', month: 'short', day: 'numeric' });
  } catch {
    return String(dateStr).slice(0, 10);
  }
};

export default function HealthPage() {
  const { user } = useAuth();
  const [searchParams, setSearchParams] = useSearchParams();
  const farmId = user?.farm_id || searchParams.get('farm_id');
  const initialAnimalId = searchParams.get('animal_id') || '';

  const [records, setRecords] = useState([]);
  const [animals, setAnimals] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({
    record_type: '',
    animal_id: initialAnimalId,
    from: '',
    to: ''
  });
  const [showForm, setShowForm] = useState(!!initialAnimalId);
  const [saving, setSaving] = useState(false);

  const [form, setForm] = useState({
    animal_id: initialAnimalId,
    record_type: 'vaccination',
    record_date: new Date().toISOString().split('T')[0],
    description: '',
    medication_name: '',
    dosage: '',
    next_date: '',
    cost: '',
    notes: ''
  });

  const load = useCallback(async () => {
    if (!farmId) return;
    setLoading(true);
    try {
      const activeFilters = {};
      if (filters.record_type) activeFilters.record_type = filters.record_type;
      if (filters.animal_id) activeFilters.animal_id = filters.animal_id;
      if (filters.from) activeFilters.from = filters.from;
      if (filters.to) activeFilters.to = filters.to;

      const [res, animRes] = await Promise.allSettled([
        healthService.list(farmId, activeFilters),
        animalService.list(farmId, 1, 250, { status: 'active' })
      ]);
      if (res.status === 'fulfilled') setRecords(res.value.data?.data || []);
      if (animRes.status === 'fulfilled') setAnimals(animRes.value.data?.data || []);
    } catch {
      toast.error('Sağlık kayıtları yüklenemedi');
      setRecords([]);
    } finally {
      setLoading(false);
    }
  }, [farmId, filters]);

  useEffect(() => {
    load();
  }, [load]);

  const handleAdd = async (e) => {
    e.preventDefault();
    if (!form.animal_id || !form.record_date) {
      toast.error('Hayvan ve kayıt tarihi zorunludur');
      return;
    }

    setSaving(true);
    try {
      const payload = {
        animal_id: parseInt(form.animal_id, 10),
        record_type: form.record_type,
        record_date: form.record_date,
        description: form.description?.trim() || null,
        medication_name: form.medication_name?.trim() || null,
        dosage: form.dosage?.trim() || null,
        next_date: form.next_date || null,
        cost: form.cost !== '' && form.cost != null && !isNaN(form.cost) ? parseFloat(form.cost) : null,
        notes: form.notes?.trim() || null
      };

      await healthService.create(farmId, payload);
      toast.success(payload.next_date ? 'Sağlık kaydı ve hatırlatıcı görev eklendi' : 'Sağlık kaydı eklendi');
      setShowForm(false);
      setForm({
        animal_id: '',
        record_type: 'vaccination',
        record_date: new Date().toISOString().split('T')[0],
        description: '',
        medication_name: '',
        dosage: '',
        next_date: '',
        cost: '',
        notes: ''
      });
      load();
    } catch (err) {
      toast.error(err.response?.data?.error || 'Kayıt işlemi başarısız');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (record) => {
    if (!window.confirm('Bu sağlık kaydını silmek / arşivlemek istediğinizden emin misiniz?')) {
      return;
    }
    try {
      await healthService.delete(record.id, farmId);
      toast.success('Kayıt silindi');
      load();
    } catch {
      toast.error('Silme işlemi başarısız');
    }
  };

  const handleResetFilters = () => {
    setFilters({ record_type: '', animal_id: '', from: '', to: '' });
    setSearchParams({});
  };

  return (
    <div className="space-y-5 pb-8">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
            💊 Sağlık ve Tedavi Yönetimi
          </h1>
          <p className="text-sm text-gray-500">Aşı, parazit mücadelesi, ilaçlama ve klinik muayene kayıtları</p>
        </div>
        <button
          onClick={() => setShowForm(!showForm)}
          className={`btn-primary flex items-center justify-center gap-1.5 text-xs py-2 px-4 shadow-sm transition-colors ${
            showForm ? 'bg-gray-600 hover:bg-gray-700 text-white' : ''
          }`}
        >
          {showForm ? '✕ Formu Kapat' : <><Plus className="w-4 h-4" /> Yeni Sağlık Kaydı</>}
        </button>
      </div>

      {/* Kayıt Ekleme Formu */}
      {showForm && (
        <div className="card border-purple-100 bg-purple-50/30 animate-in fade-in slide-in-from-top-3 shadow-md">
          <div className="flex items-center justify-between mb-4 pb-2 border-b border-purple-100">
            <h2 className="text-base font-bold text-purple-900 flex items-center gap-2">
              <Plus className="w-4 h-4 text-purple-600" /> Yeni Sağlık / Aşı Kaydı Gir
            </h2>
            <button onClick={() => setShowForm(false)} className="text-gray-400 hover:text-gray-600 text-sm">✕</button>
          </div>

          <form onSubmit={handleAdd} className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div>
                <label className="block text-xs font-bold text-gray-600 uppercase mb-1">Hayvan Seçin *</label>
                <select
                  value={form.animal_id}
                  onChange={e => setForm({ ...form, animal_id: e.target.value })}
                  className="input-field"
                  required
                >
                  <option value="">Hayvan Seçiniz...</option>
                  {animals.map(a => (
                    <option key={a.id} value={a.id}>
                      {a.name} ({a.code}) - {a.species}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-xs font-bold text-gray-600 uppercase mb-1">Kayıt Türü *</label>
                <select
                  value={form.record_type}
                  onChange={e => setForm({ ...form, record_type: e.target.value })}
                  className="input-field"
                >
                  {Object.entries(RECORD_TYPES).map(([k, v]) => (
                    <option key={k} value={k}>{v.label}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-xs font-bold text-gray-600 uppercase mb-1">Uygulama Tarihi *</label>
                <input
                  type="date"
                  value={form.record_date}
                  onChange={e => setForm({ ...form, record_date: e.target.value })}
                  className="input-field"
                  required
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-gray-600 uppercase mb-1">İlaç / Aşı / Teşhis Adı</label>
                <input
                  type="text"
                  placeholder="Örn: Karma Aşı, Parazit İlacı, Mastitis Tedavisi"
                  value={form.medication_name}
                  onChange={e => setForm({ ...form, medication_name: e.target.value })}
                  className="input-field"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-gray-600 uppercase mb-1">Dozaj / Miktar</label>
                <input
                  type="text"
                  placeholder="Örn: 2ml subkutan, 1 tablet"
                  value={form.dosage}
                  onChange={e => setForm({ ...form, dosage: e.target.value })}
                  className="input-field"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-gray-600 uppercase mb-1">Tedavi Maliyeti (₺)</label>
                <input
                  type="number"
                  step="0.01"
                  min="0"
                  placeholder="0.00"
                  value={form.cost}
                  onChange={e => setForm({ ...form, cost: e.target.value })}
                  className="input-field"
                />
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-bold text-gray-600 uppercase mb-1 flex items-center gap-1.5">
                  <Bell className="w-3.5 h-3.5 text-purple-600" />
                  Sonraki Hatırlatma / Tekrar Tarihi
                </label>
                <input
                  type="date"
                  value={form.next_date}
                  onChange={e => setForm({ ...form, next_date: e.target.value })}
                  className="input-field"
                />
                <p className="text-[10px] text-gray-400 mt-1">Doldurulursa sistem otomatik görev ve bildirim oluşturur.</p>
              </div>

              <div>
                <label className="block text-xs font-bold text-gray-600 uppercase mb-1">Klinik Açıklama / Bulgular</label>
                <textarea
                  placeholder="Hastalık belirtileri, muayene sonucu veya veteriner hekim tavsiyeleri..."
                  value={form.description}
                  onChange={e => setForm({ ...form, description: e.target.value })}
                  className="input-field"
                  rows={2}
                />
              </div>
            </div>

            <div className="flex gap-3 pt-2">
              <button
                type="button"
                onClick={() => setShowForm(false)}
                className="btn-secondary flex-1"
              >
                Vazgeç
              </button>
              <button
                type="submit"
                disabled={saving}
                className="btn-primary flex-1 bg-purple-700 hover:bg-purple-800 border-none shadow-sm"
              >
                {saving ? 'Kaydediliyor...' : 'Sağlık Kaydını Sisteme İşle'}
              </button>
            </div>
          </form>
        </div>
      )}

      {/* Filtreler */}
      <div className="card p-4 shadow-sm border border-gray-100">
        <div className="flex flex-col md:flex-row gap-3">
          <div className="flex-1">
            <select
              value={filters.animal_id}
              onChange={e => setFilters({ ...filters, animal_id: e.target.value })}
              className="input-field text-xs"
            >
              <option value="">Tüm Hayvanlar</option>
              {animals.map(a => (
                <option key={a.id} value={a.id}>
                  {a.name} ({a.code})
                </option>
              ))}
            </select>
          </div>

          <div className="w-full md:w-48">
            <select
              value={filters.record_type}
              onChange={e => setFilters({ ...filters, record_type: e.target.value })}
              className="input-field text-xs"
            >
              <option value="">Tüm Kayıt Türleri</option>
              {Object.entries(RECORD_TYPES).map(([k, v]) => (
                <option key={k} value={k}>{v.label}</option>
              ))}
            </select>
          </div>

          <div className="flex items-center gap-2">
            <input
              type="date"
              title="Başlangıç Tarihi"
              value={filters.from}
              onChange={e => setFilters({ ...filters, from: e.target.value })}
              className="input-field text-xs"
            />
            <span className="text-gray-400 text-xs">-</span>
            <input
              type="date"
              title="Bitiş Tarihi"
              value={filters.to}
              onChange={e => setFilters({ ...filters, to: e.target.value })}
              className="input-field text-xs"
            />
          </div>

          <div className="flex items-center gap-2">
            <button
              onClick={load}
              className="btn-primary flex items-center justify-center gap-1.5 text-xs py-2 px-5"
            >
              <Filter className="w-3.5 h-3.5" /> Filtrele
            </button>
            {(filters.record_type || filters.animal_id || filters.from || filters.to) && (
              <button
                onClick={handleResetFilters}
                className="btn-secondary text-xs p-2"
                title="Filtreleri Temizle"
              >
                <X className="w-4 h-4" />
              </button>
            )}
          </div>
        </div>
      </div>

      {/* Kayıt Listesi Tablosu */}
      <div className="card p-0 overflow-hidden shadow-sm border border-gray-100">
        <div className="overflow-x-auto">
          {loading ? (
            <div className="flex items-center justify-center py-16">
              <div className="w-8 h-8 border-4 border-purple-600 border-t-transparent rounded-full animate-spin" />
            </div>
          ) : records.length === 0 ? (
            <div className="text-center py-16 text-gray-400">
              <div className="text-4xl mb-2">💊</div>
              <p className="font-semibold text-gray-700 text-sm">Sağlık kaydı bulunamadı</p>
              <p className="text-xs text-gray-400 mt-1">Seçili kriterlerde kayıt yok veya henüz eklenmedi.</p>
              <button
                onClick={() => setShowForm(true)}
                className="mt-3 btn-primary text-xs py-2 px-4 inline-flex items-center gap-1"
              >
                <Plus className="w-3.5 h-3.5" /> İlk Kaydı Ekle
              </button>
            </div>
          ) : (
            <table className="w-full text-xs">
              <thead className="bg-gray-50 border-b border-gray-100">
                <tr>
                  <th className="text-left px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Tarih</th>
                  <th className="text-left px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Tür</th>
                  <th className="text-left px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Hayvan</th>
                  <th className="text-left px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Tanı / İlaç</th>
                  <th className="text-left px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Dozaj</th>
                  <th className="text-right px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Maliyet</th>
                  <th className="text-right px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">İşlem</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {records.map(r => (
                  <tr key={r.id} className="hover:bg-purple-50/20 transition-colors group">
                    <td className="px-6 py-4 whitespace-nowrap text-gray-600 font-medium">
                      {formatDate(r.record_date)}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`px-2 py-1 rounded-lg text-[10px] font-black uppercase tracking-wider ${RECORD_TYPES[r.record_type]?.color || 'bg-gray-100 text-gray-700'}`}>
                        {RECORD_TYPES[r.record_type]?.label || r.record_type}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <p className="font-bold text-gray-900">
                        {r.animal?.name || `Hayvan #${r.animal_id}`}
                      </p>
                      {r.animal?.code && (
                        <p className="text-[10px] text-gray-400 font-mono">{r.animal.code}</p>
                      )}
                    </td>
                    <td className="px-6 py-4 max-w-xs">
                      <p className="font-bold text-gray-800 truncate">{r.medication_name || r.description || '—'}</p>
                      {r.description && r.medication_name && (
                        <p className="text-[10px] text-gray-500 truncate">{r.description}</p>
                      )}
                    </td>
                    <td className="px-6 py-4 text-gray-500 whitespace-nowrap">
                      {r.dosage || '—'}
                    </td>
                    <td className="px-6 py-4 text-right font-black text-gray-900 whitespace-nowrap">
                      {r.cost ? `₺${parseFloat(r.cost).toLocaleString('tr-TR')}` : '—'}
                    </td>
                    <td className="px-6 py-4 text-right whitespace-nowrap">
                      <button
                        onClick={() => handleDelete(r)}
                        className="p-1.5 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors opacity-80 group-hover:opacity-100"
                        title="Kaydı Arşivle / Sil"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </div>
  );
}